function identity<T>(value: T): T {
  return value;
}

const n = identity(42);       // number
const s = identity('hello');  // string
const explicit = identity<boolean>(true);

interface Entity { id: string; }

class MemoryRepo<T extends Entity> {
  private store = new Map<string, T>();

  save(entity: T): void {
    this.store.set(entity.id, entity);
  }

  find(id: string): T | undefined {
    return this.store.get(id);
  }
}

const users = new MemoryRepo<{ id: string; name: string }>();

interface Serializer<T> {
  serialize(value: T): string;
  deserialize(raw: string): T;
}

const jsonSerializer: Serializer<User> = {
  serialize: (u) => JSON.stringify(u),
  deserialize: (raw) => JSON.parse(raw) as User,
};

function createArray<T>(item: T): T[] {
  return [item];
}

const nums = createArray(0);           // number[]
const empty = createArray([]);         // never[][] — T inferred as never[]
const fixed = createArray<number[]>([]); // number[][]
